<?php declare(strict_types=1);require_once __DIR__.'/../config/auth.php';page_require(['ADMIN']);?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Monitor SaladCloud — Hache</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#172033;font-family:Manrope,Arial,sans-serif}.wrap{width:min(1180px,94%);margin:0 auto;padding:78px 0 32px}.sub{color:#64748b;margin:6px 0 18px}.top{display:flex;align-items:end;justify-content:space-between;gap:16px;flex-wrap:wrap}.summary{display:flex;gap:8px;flex-wrap:wrap}.pill{padding:7px 10px;border-radius:99px;font-size:12px;font-weight:800;background:#fff;border:1px solid #e5eaf0}.pill.warn{background:#fffbeb;border-color:#f59e0b;color:#92400e}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(285px,1fr));gap:12px}.card{background:#fff;border:1px solid #e5eaf0;border-radius:16px;padding:16px;box-shadow:0 4px 16px #0f172a08}.card.stale{border-color:#f59e0b}.head{display:flex;gap:10px;align-items:start;justify-content:space-between}.name{font-weight:900;word-break:break-word}.gpu{font-size:13px;color:#64748b;margin-top:4px}.state{width:11px;height:11px;border-radius:50%;margin-top:4px}.green{background:#16a34a}.yellow{background:#f59e0b}.red{background:#dc2626}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:15px}.metric{background:#f8fafc;border-radius:10px;padding:9px}.label{font-size:10px;text-transform:uppercase;color:#64748b;font-weight:800}.value{font-size:18px;font-weight:900;margin-top:2px}.small{font-size:12px;color:#64748b;margin-top:12px}.small.warn{color:#92400e;font-weight:800}.empty{padding:28px;text-align:center;background:#fff;border-radius:16px;color:#64748b}.error{color:#991b1b;background:#fff1f2}.history{height:30px;display:flex;align-items:end;gap:2px;margin-top:12px}.bar{width:5px;min-height:2px;background:#2563eb;border-radius:3px 3px 0 0}@media(max-width:560px){.wrap{width:92%;padding-top:70px}.metrics{grid-template-columns:1fr 1fr}}</style></head><body><main class="wrap"><div class="top"><div><h1>Monitor SaladCloud</h1><p class="sub">Proyecto prl-tests · snapshot seguro · actualización cada 5 minutos.</p></div><div class="summary" id="summary"></div></div><div id="content" class="empty">Cargando monitor…</div></main><script>
const c=document.getElementById('content'),s=document.getElementById('summary'),esc=v=>String(v??'—').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x])),n=v=>v==null?'—':Number(v).toLocaleString('es-MX',{maximumFractionDigits:2}),store='hache-salad-history-v1';let hasData=false;
function history(groups){let old=[];try{old=JSON.parse(localStorage.getItem(store)||'[]')}catch(e){}old.push({at:Date.now(),g:Object.fromEntries(groups.map(x=>[x.group,Number(x.metrics?.hashrate_ths||0)]))});old=old.filter(x=>x.at>Date.now()-86400000).slice(-288);try{localStorage.setItem(store,JSON.stringify(old))}catch(e){}return old}
function ageText(seconds){if(seconds==null)return 'antigüedad desconocida';if(seconds<90)return 'actualizado hace menos de 2 min';const min=Math.round(seconds/60);return 'datos de hace '+min+' min'}
function render(d){const groups=d.groups||[],h=history(groups),counts={green:0,yellow:0,red:0},partial=groups.filter(x=>x.stale).length;groups.forEach(x=>counts[x.health]=(counts[x.health]||0)+1);s.innerHTML=`<span class="pill">🟢 ${counts.green} estable</span><span class="pill">🟡 ${counts.yellow} revisar</span><span class="pill">🔴 ${counts.red} alerta</span><span class="pill ${d.stale||partial?'warn':''}">${esc(ageText(d.age_seconds))}${partial?' · '+partial+' grupo(s) sin refrescar':''}</span>`;c.className='grid';c.innerHTML=groups.map(x=>{const m=x.metrics||{},series=h.map(a=>a.g?.[x.group]||0),max=Math.max(1,...series);return `<article class="card ${x.stale?'stale':''}"><div class="head"><div><div class="name">${esc(x.display_name)}</div><div class="gpu">${esc(m.gpu||'Sin datos de SRBMiner')}</div></div><i class="state ${esc(x.health)}" title="${esc(x.health)}"></i></div><div class="metrics"><div class="metric"><div class="label">TH/s actual</div><div class="value">${n(m.hashrate_ths)}</div></div><div class="metric"><div class="label">Media 15 min</div><div class="value">${n(m.hashrate_15m_ths)}</div></div><div class="metric"><div class="label">Potencia / temp.</div><div class="value">${n(m.watts)} W · ${n(m.temperature_c)}°</div></div><div class="metric"><div class="label">Vent. / shares</div><div class="value">${n(m.fan_percent)}% · ${n(m.shares?.accepted)}</div></div></div><div class="history" aria-label="Histórico local de 24 horas">${series.map(v=>`<i class="bar" style="height:${Math.max(2,Math.round(v/max*30))}px"></i>`).join('')}</div><div class="small">Grupo: ${esc(x.state)} · Logs: ${esc(m.last_log_at||'sin lectura')}</div>${x.stale?'<div class="small warn">Último dato válido conservado; este grupo no pudo refrescarse.</div>':''}</article>`}).join('')||'<div class="empty">No hay Container Groups disponibles.</div>';hasData=true}
async function load(){try{const r=await fetch('/api/salad-monitor.php',{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'No disponible');render(d)}catch(e){if(hasData){s.insertAdjacentHTML('beforeend','<span class="pill warn">No se pudo refrescar ahora; se mantienen los últimos datos.</span>')}else{c.className='empty error';c.textContent=e.message}}}
load();setInterval(load,300000)
</script></body></html>
